// src/api/client.ts
var API_BASE = "/api";
var apiClient = {
	async getProducts() {
		try {
			const res = await fetch(`${API_BASE}/products`);
			if (!res.ok) throw new Error("Failed to fetch products");
			return (await res.json()).products || [];
		} catch (err) {
			console.error("getProducts error:", err);
			const cached = localStorage.getItem("argo_products_cache");
			return cached ? JSON.parse(cached) : [];
		}
	},
	async getProduct(id) {
		try {
			const res = await fetch(`${API_BASE}/products/${id}`);
			if (!res.ok) return null;
			return (await res.json()).product || null;
		} catch (err) {
			console.error("getProduct error:", err);
			return null;
		}
	},
	async createProduct(product) {
		return (await (await fetch(`${API_BASE}/products`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(product)
		})).json()).product;
	},
	async updateProduct(id, product) {
		return (await (await fetch(`${API_BASE}/products/${id}`, {
			method: "PUT",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(product)
		})).json()).product;
	},
	async deleteProduct(id) {
		return (await (await fetch(`${API_BASE}/products/${id}`, { method: "DELETE" })).json()).success;
	},
	async getOrders() {
		return (await (await fetch(`${API_BASE}/orders`)).json()).orders || [];
	},
	async createOrder(orderPayload) {
		return (await (await fetch(`${API_BASE}/orders`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(orderPayload)
		})).json()).order;
	},
	async updateOrderStatus(id, status, paymentStatus) {
		return (await (await fetch(`${API_BASE}/orders/${id}`, {
			method: "PATCH",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				orderStatus: status,
				paymentStatus
			})
		})).json()).success;
	},
	async getQuotes() {
		return (await (await fetch(`${API_BASE}/quotes`)).json()).quotes || [];
	},
	async createQuote(quote) {
		return (await fetch(`${API_BASE}/quotes`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(quote)
		})).json();
	},
	async updateQuoteStatus(id, status) {
		return (await (await fetch(`${API_BASE}/quotes/${id}`, {
			method: "PATCH",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ status })
		})).json()).success;
	},
	async getSamples() {
		return (await (await fetch(`${API_BASE}/samples`)).json()).samples || [];
	},
	async createSample(sample) {
		return (await fetch(`${API_BASE}/samples`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(sample)
		})).json();
	},
	async updateSampleStatus(id, status) {
		return (await (await fetch(`${API_BASE}/samples/${id}`, {
			method: "PATCH",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ status })
		})).json()).success;
	},
	async getSalesReps() {
		return (await (await fetch(`${API_BASE}/sales-reps`)).json()).salesReps || [];
	},
	async saveSalesRep(rep) {
		const method = rep.id ? "PUT" : "POST";
		const url = rep.id ? `${API_BASE}/sales-reps/${rep.id}` : `${API_BASE}/sales-reps`;
		return (await (await fetch(url, {
			method,
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(rep)
		})).json()).salesRep;
	},
	async deleteSalesRep(id) {
		return (await (await fetch(`${API_BASE}/sales-reps/${id}`, { method: "DELETE" })).json()).success;
	},
	async getSettings() {
		return (await (await fetch(`${API_BASE}/settings`)).json()).settings;
	},
	async updateSettings(settings) {
		return (await (await fetch(`${API_BASE}/settings`, {
			method: "PUT",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(settings)
		})).json()).settings;
	},
	async uploadFile(file) {
		const formData = new FormData();
		formData.append("file", file);
		const res = await fetch(`${API_BASE}/upload`, {
			method: "POST",
			body: formData
		});
		if (!res.ok) throw new Error("File upload failed");
		return res.json();
	},
	async adminLogin(username, password) {
		return (await fetch(`${API_BASE}/admin/login`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				username,
				password
			})
		})).json();
	},
	async createPayPalOrder(orderId, amount) {
		return {
			id: `PAYID-${Date.now()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`,
			status: "CREATED"
		};
	},
	async capturePayPalPayment(paypalOrderId, orderId) {
		await this.updateOrderStatus(orderId, "processing", "Approved");
		return {
			status: "COMPLETED",
			id: paypalOrderId
		};
	}
};
